E("s9f-u1-theorie-preuves", 1, ["SC9.1.5"], 2, "var", varset([
  function () {
    return mcq("Les galaxies lointaines montrent un décalage vers le rouge : leur lumière est étirée vers de plus grandes longueurs d'onde. Quelle conclusion les scientifiques en tirent-ils?",
      "Les galaxies s'éloignent de nous : l'univers est en expansion, ce qui appuie la théorie du Big Bang",
      ["Les galaxies lointaines se rapprochent toutes de nous : l'univers entier se contracte rapidement vers un point central unique situé près de notre galaxie", "Les galaxies lointaines sont simplement et naturellement plus rouges que la nôtre, sans qu'il y ait le moindre mouvement réel entre elles dans l'espace", "La lumière vieillit en voyageant, et le décalage ne dit rien du mouvement des galaxies"],
      "Le décalage vers le rouge des galaxies lointaines est une preuve directe de l'expansion de l'univers. <b>Les galaxies s'éloignent de nous : l'univers est en expansion</b>.", {});
  },
  function () {
    return mcq("Le rayonnement fossile (fond diffus cosmologique) est un faible rayonnement micro-onde qui arrive de toutes les directions du ciel. Pourquoi appuie-t-il la théorie du Big Bang?",
      "C'est la chaleur résiduelle de l'univers primitif très chaud, refroidie par des milliards d'années d'expansion",
      ["C'est simplement le rayonnement combiné de toutes les étoiles actuelles de l'univers, additionné ensemble dans toutes les directions du ciel nocturne", "C'est un signal faible produit par l'atmosphère terrestre elle-même, que les instruments mesurent par erreur comme s'il venait de l'espace lointain", "C'est la preuve que l'univers a toujours eu exactement la même température qu'aujourd'hui"],
      "Un univers né chaud et dense devait laisser un rayonnement résiduel refroidi par l'expansion : c'est ce fond diffus. <b>C'est la chaleur résiduelle de l'univers primitif très chaud</b>.", {});
  },
  function () {
    return mcq("La théorie de l'univers oscillant propose que l'expansion finira par s'inverser en contraction, puis rebondir. Qu'est-ce qui la distingue de la théorie du Big Bang à un seul début?",
      "Elle propose une suite sans fin de cycles d'expansion et de contraction, plutôt qu'un seul commencement suivi d'expansion continue",
      ["Elle nie complètement que les galaxies de l'univers s'éloignent les unes des autres à l'heure actuelle, contrairement à toutes les observations des télescopes", "Elle affirme catégoriquement que l'univers actuel n'a ni température de fond mesurable ni aucun rayonnement résiduel d'aucune sorte dans aucune direction", "Elle place la Terre exactement au centre de chaque cycle d'expansion et de contraction"],
      "L'univers oscillant remplace le commencement unique par des cycles répétés d'expansion et de contraction. <b>Elle propose une suite sans fin de cycles d'expansion et de contraction</b>.", {});
  },
  function () {
    return mcq("La théorie de l'état stationnaire proposait un univers éternel qui crée de la matière en s'étendant. Pourquoi les scientifiques l'ont-ils rejetée?",
      "Le rayonnement fossile découvert dans le ciel contredit un univers éternel et inchangé : l'univers primitif était différent d'aujourd'hui",
      ["Parce que les auteurs de la théorie l'ont retirée et abandonnée eux-mêmes dès la toute première observation astronomique qui semblait la contredire un peu", "Parce qu'elle prédisait en détail le décalage vers le rouge des galaxies, un phénomène que les télescopes du monde entier n'ont pourtant jamais observé", "Parce qu'un univers éternel aurait dû être complètement noir et sans aucune étoile visible"],
      "Un univers éternel et inchangé ne peut pas avoir de rayonnement résiduel d'une époque chaude : la découverte du fond diffus l'a réfutée. <b>Le rayonnement fossile contredit un univers éternel et inchangé</b>.", {});
  },
  function () {
    return mcq("L'univers contient environ 75 % d'hydrogène et 25 % d'hélium en masse, presque partout où on le mesure. Pourquoi ce rapport appuie-t-il la théorie du Big Bang?",
      "La théorie prédit justement ces proportions à partir des réactions nucléaires de l'univers primitif chaud et dense",
      ["Parce que les étoiles actuelles de l'univers produisent exactement ce rapport hydrogène-hélium et l'ont imposé à tout l'univers entier en une seule année récente", "Parce que l'hydrogène et l'hélium sont les deux seuls et uniques éléments chimiques qui existent dans tout l'univers connu, sans aucune exception nulle part", "Parce que ce rapport prouve que l'univers n'a jamais été ni plus chaud ni plus dense qu'aujourd'hui"],
      "Les proportions H/He prédites par les calculs sur l'univers primitif correspondent aux mesures : c'est une confirmation quantitative. <b>La théorie prédit justement ces proportions</b>.", {});
  }
]), ["Associe l'observation à la théorie qui la prédit vraiment.", "Un univers éternel et inchangé ne peut pas laisser de chaleur résiduelle d'un début chaud."]);

/* CR denomination tranche additions (Nov 20, 2026): written
   entries closing the exact CR denomination gaps named in
   CR-Denomination-Gap-2026-11-20.md: s9f-u1-cr-modele-preuves closes Unit 1 Test 1 (4 marks, Level 3); s9f-u1-cr-nebulaire closes Unit 1 Test 2 (2 marks, Level 3); s9f-u1-cr-expansion-preuves closes Unit 1 Test 3 (4 marks, Level 3). SME-flagged for the
   specialist pass. */
E("s9f-u1-cr-modele-preuves", 1, ["SC9.1.1", "SC9.1.2"], 3, "var", varset([
  function () { return textq("Deux observations sont rapportées : (1) au télescope, Vénus montre un cycle complet de phases, comme une petite Lune, et elle paraît beaucoup plus grosse dans certaines phases que dans d’autres; (2) Mars avance habituellement parmi les étoiles, mais pendant quelques semaines, il semble reculer avant de reprendre son avance. (a) Explique comment l’observation (1) appuie le modèle héliocentrique (1 point). (b) Explique comment l’observation (2) appuie le modèle héliocentrique (1 point). (c) Explique pourquoi le modèle géocentrique explique mal l’une de ces deux observations, au choix (1 point). (d) Pour l’une des deux observations, distingue le mouvement apparent observé du mouvement réel qui le produit (1 point). (4 points)", ["(a) phases complètes de Vénus : elle orbite autour du Soleil, donc on voit sa face éclairée sous tous les angles", "(b) recul de Mars : la Terre, plus rapide, dépasse Mars sur son orbite, ce qui le fait paraître reculer", "(c) géocentrique : Vénus resterait entre la Terre et le Soleil et ne montrerait jamais de phase pleine", "(d) Mars : recul apparent vu de la Terre; en réalité Mars avance toujours, c’est la Terre qui le dépasse"], "<b>Réponse modèle :</b> (a) Vénus montre des phases complètes, y compris une phase pleine, et sa taille apparente change beaucoup. Cela s’explique si Vénus orbite autour du Soleil : elle passe tantôt entre la Terre et le Soleil, tantôt de l’autre côté du Soleil, et nous voyons sa face éclairée sous tous les angles, de près comme de loin. (b) Le recul de Mars s’explique naturellement si la Terre et Mars orbitent toutes deux autour du Soleil : la Terre, sur une orbite plus petite, avance plus vite et dépasse Mars; pendant le dépassement, Mars semble reculer par rapport aux étoiles lointaines. (c) Le modèle géocentrique explique mal les phases de Vénus : si Vénus tournait autour de la Terre en restant toujours entre la Terre et le Soleil, elle ne pourrait jamais apparaître pleine, car sa face éclairée serait tournée vers le Soleil, à l’opposé de nous. (d) Pour Mars : le mouvement apparent est le recul observé dans le ciel; le mouvement réel est l’avance continue de Mars sur son orbite. Le recul n’existe que du point de vue de la Terre en mouvement.<br><br><b>Points d’attribution :</b> 1 point pour l’observation (1) correctement reliée à l’orbite de Vénus autour du Soleil. 1 point pour l’observation (2) correctement expliquée par le dépassement de Mars par la Terre. 1 point pour une difficulté réelle du modèle géocentrique sur l’une des deux observations. 1 point pour la distinction correcte entre mouvement apparent et mouvement réel.", {}); },
  function () { return textq("Deux observations sont rapportées : (1) au télescope, quatre petits points lumineux changent de position nuit après nuit autour de Jupiter, passant tantôt d’un côté, tantôt de l’autre, et disparaissant parfois derrière la planète; (2) Vénus ne s’éloigne jamais beaucoup du Soleil dans le ciel, et sa taille apparente varie beaucoup au fil des mois. (a) Explique comment l’observation (1) appuie le modèle héliocentrique (1 point). (b) Explique comment l’observation (2) appuie le modèle héliocentrique (1 point). (c) Explique pourquoi le modèle géocentrique explique mal l’une de ces deux observations, au choix (1 point). (d) Pour l’une des deux observations, distingue le mouvement apparent observé du mouvement réel qui le produit (1 point). (4 points)", ["(a) les quatre points sont des lunes qui orbitent autour de Jupiter : tout ne tourne donc pas autour de la Terre", "(b) Vénus reste près du Soleil et change de taille parce qu’elle orbite autour du Soleil, à des distances très variables de la Terre", "(c) géocentrique : il exige que tous les corps célestes tournent autour de la Terre, ce que les lunes de Jupiter contredisent", "(d) lunes de Jupiter : leur va-et-vient apparent est la vue, presque par la tranche, de leurs orbites réelles autour de Jupiter"], "<b>Réponse modèle :</b> (a) Les quatre points sont des lunes qui orbitent autour de Jupiter. Leur existence montre qu’un corps céleste peut être le centre du mouvement d’autres corps : tout ne tourne pas autour de la Terre, ce qui retire son principal pilier au modèle géocentrique et s’accorde avec un modèle où les planètes ont leurs propres mouvements autour du Soleil. (b) Vénus orbite autour du Soleil, sur une orbite plus petite que celle de la Terre : vue de la Terre, elle reste donc toujours près du Soleil dans le ciel, et sa distance à la Terre varie énormément, ce qui explique les grands changements de sa taille apparente. (c) Le modèle géocentrique explique mal l’observation (1) : il exige que tous les corps célestes tournent autour de la Terre, alors que les lunes observées tournent manifestement autour de Jupiter. (d) Pour les lunes de Jupiter : le mouvement apparent est leur va-et-vient de part et d’autre de la planète, avec des disparitions; le mouvement réel est leur orbite continue autour de Jupiter, vue presque par la tranche depuis la Terre, ce qui explique aussi leurs passages derrière la planète.<br><br><b>Points d’attribution :</b> 1 point pour l’observation (1) correctement reliée à des orbites autour d’un centre autre que la Terre. 1 point pour l’observation (2) correctement reliée à l’orbite de Vénus autour du Soleil. 1 point pour une difficulté réelle du modèle géocentrique sur l’une des deux observations. 1 point pour la distinction correcte entre mouvement apparent et mouvement réel.", {}); },
  function () { return textq("Deux observations sont rapportées : (1) Mars semble parfois reculer parmi les étoiles pendant quelques semaines avant de reprendre son avance; (2) les étoiles proches ne montrent aucun déplacement annuel mesurable à l’œil nu par rapport aux étoiles lointaines. (a) Explique comment l’observation (1) appuie le modèle héliocentrique (1 point). (b) Explique comment l’observation (2) appuie le modèle héliocentrique une fois la distance des étoiles prise en compte (1 point). (c) Explique pourquoi le modèle géocentrique explique mal l’une de ces deux observations, au choix (1 point). (d) Pour l’une des deux observations, distingue le mouvement apparent observé du mouvement réel qui le produit (1 point). (4 points)", ["(a) recul de Mars : effet du dépassement par la Terre, plus rapide sur son orbite", "(b) aucun déplacement visible : le modèle prévoit un léger déplacement annuel, la parallaxe, mais les étoiles sont si loin qu’il est trop petit pour l’œil nu", "(c) géocentrique : le recul de Mars y exige des cercles ajoutés artificiels, les épicycles, sans cause réelle", "(d) parallaxe : les étoiles proches semblent se déplacer légèrement; en réalité, c’est la Terre qui change de position sur son orbite"], "<b>Réponse modèle :</b> (a) Si la Terre et Mars orbitent autour du Soleil, la Terre, plus rapide, dépasse périodiquement Mars; pendant ce dépassement, Mars semble reculer parmi les étoiles. Le modèle héliocentrique produit donc ce recul sans aucun mécanisme ajouté. (b) Le modèle héliocentrique prévoit que les étoiles proches semblent se déplacer légèrement au fil de l’année, parce que la Terre les observe depuis des positions opposées de son orbite : c’est la parallaxe stellaire. Ce déplacement existe, mais il est minuscule, car les étoiles sont immensément plus loin que tout objet du système solaire; il est donc invisible à l’œil nu et n’apparaît qu’avec des instruments précis, exactement comme le prévoit le modèle une fois l’échelle des distances comprise. (c) Le modèle géocentrique explique mal le recul de Mars : la Terre y étant immobile, il faut ajouter des cercles sur les orbites, les épicycles, uniquement pour reproduire le recul, sans qu’aucun mouvement réel ne le cause. (d) Pour la parallaxe : le mouvement apparent est le léger déplacement des étoiles proches par rapport aux étoiles lointaines; le mouvement réel est celui de la Terre, qui change de côté de son orbite en six mois. Les étoiles ne font pas ce va-et-vient : c’est le point d’observation qui bouge.<br><br><b>Points d’attribution :</b> 1 point pour l’observation (1) correctement expliquée par le dépassement de Mars par la Terre. 1 point pour la parallaxe prévue mais minuscule, en raison de l’immense distance des étoiles. 1 point pour une difficulté réelle du modèle géocentrique sur l’une des deux observations. 1 point pour la distinction correcte entre mouvement apparent et mouvement réel.", {}); },
  function () { return textq("Deux observations sont rapportées : (1) Vénus apparaît tantôt comme une étoile du matin, visible avant le lever du Soleil, tantôt comme une étoile du soir, visible après son coucher, et elle montre un cycle complet de phases; (2) quatre lunes changent de position autour de Jupiter nuit après nuit. (a) Explique comment l’observation (1) appuie le modèle héliocentrique (1 point). (b) Explique comment l’observation (2) appuie le modèle héliocentrique (1 point). (c) Explique pourquoi le modèle géocentrique explique mal l’une de ces deux observations, au choix (1 point). (d) Pour l’une des deux observations, distingue le mouvement apparent observé du mouvement réel qui le produit (1 point). (4 points)", ["(a) Vénus orbite autour du Soleil : ses phases complètes et ses positions du matin et du soir suivent sa place sur cette orbite", "(b) les lunes orbitent autour de Jupiter : la Terre n’est pas le centre de tous les mouvements célestes", "(c) géocentrique : des lunes qui tournent autour de Jupiter contredisent l’exigence que tout tourne autour de la Terre", "(d) Vénus : étoile du matin ou du soir selon le côté du Soleil où elle se trouve; en réalité, elle avance continûment sur son orbite autour du Soleil"], "<b>Réponse modèle :</b> (a) Vénus orbite autour du Soleil, à l’intérieur de l’orbite terrestre. Selon sa position, elle se trouve d’un côté ou de l’autre du Soleil vu de la Terre, d’où ses apparitions du matin et du soir, et sa face éclairée nous apparaît sous tous les angles, d’où son cycle complet de phases. (b) Les quatre lunes orbitent autour de Jupiter : un autre corps que la Terre sert de centre à des orbites, ce qui est impossible dans un modèle strictement géocentrique et normal dans le modèle héliocentrique, où chaque planète peut avoir ses propres lunes. (c) Le modèle géocentrique explique mal l’observation (2) : il pose que tous les corps célestes tournent autour de la Terre, alors que ces lunes tournent autour de Jupiter. (d) Pour Vénus : le mouvement apparent est son passage du statut d’étoile du soir à celui d’étoile du matin; le mouvement réel est son avance continue sur son orbite autour du Soleil, combinée au mouvement de la Terre, qui change sans cesse la direction dans laquelle nous la voyons par rapport au Soleil.<br><br><b>Points d’attribution :</b> 1 point pour l’observation (1) correctement reliée à l’orbite de Vénus autour du Soleil. 1 point pour l’observation (2) correctement reliée à des orbites autour d’un centre autre que la Terre. 1 point pour une difficulté réelle du modèle géocentrique sur l’une des deux observations. 1 point pour la distinction correcte entre mouvement apparent et mouvement réel.", {}); }
]), ["Traite chaque observation séparément : un appui distinct par point.", "Pour le mouvement apparent, demande-toi quel corps bouge vraiment : l’objet observé ou la Terre."]);
E("s9f-u1-cr-nebulaire", 1, ["SC9.1.6"], 3, "var", varset([
  function () { return textq("Observation : toutes les planètes du système solaire orbitent autour du Soleil dans le même sens, et presque toutes dans le même plan. (a) Explique comment l’hypothèse nébulaire rend compte de cette régularité (1 point). (b) Explique pourquoi la théorie de la collision stellaire en rend mal compte (1 point). (2 points)", ["(a) le nuage de départ tournait : en se contractant, il s’est aplati en disque, et les planètes formées dans ce disque ont hérité de son sens de rotation et de son plan", "(b) collision : de la matière arrachée par une étoile de passage serait projetée sans raison de donner des orbites régulières, toutes dans le même sens et le même plan"], "<b>Réponse modèle :</b> (a) Selon l’hypothèse nébulaire, le système solaire s’est formé d’un nuage de gaz et de poussière qui tournait lentement. En se contractant sous sa gravité, le nuage a tourné de plus en plus vite et s’est aplati en un disque. Les planètes se sont formées à l’intérieur de ce disque : elles ont donc toutes hérité du même sens de rotation et du même plan, celui du disque. (b) Dans la théorie de la collision stellaire, les planètes viendraient de matière arrachée au Soleil par une étoile passée très près. Une telle rencontre projetterait la matière de façon désordonnée; rien ne garantit qu’elle se dispose en orbites régulières, toutes dans le même sens et presque dans le même plan. La régularité observée est donc un héritage naturel du disque nébulaire, mais un hasard improbable pour la collision.<br><br><b>Points d’attribution :</b> 1 point pour le disque en rotation dont les planètes héritent le sens et le plan. 1 point pour la matière arrachée de façon désordonnée, sans raison de produire des orbites régulières.", {}); },
  function () { return textq("Observation : la composition des planètes varie avec leur distance au Soleil : les planètes proches sont petites et rocheuses, les planètes lointaines sont géantes et surtout gazeuses. (a) Explique comment l’hypothèse nébulaire rend compte de ce gradient de composition (1 point). (b) Explique pourquoi la théorie de la collision stellaire en rend mal compte, ou ce qu’elle prévoirait plutôt (1 point). (2 points)", ["(a) près du jeune Soleil, la chaleur empêchait les gaz et les glaces de se condenser : seuls la roche et le métal se sont condensés; loin du Soleil, le froid a permis aux gaz et aux glaces de s’accumuler en géantes", "(b) collision : la matière arrachée au Soleil serait partout de composition solaire et chaude; elle ne se trierait pas en roche près du Soleil et en gaz loin de lui"], "<b>Réponse modèle :</b> (a) Dans le disque nébulaire, la température diminuait avec la distance au jeune Soleil. Près du Soleil, il faisait trop chaud pour que les gaz légers et les glaces se condensent : seuls les matériaux rocheux et métalliques ont formé des grains, d’où de petites planètes rocheuses. Loin du Soleil, le froid permettait aux gaz et aux glaces de se condenser et de s’accumuler en grande quantité, d’où des géantes surtout gazeuses. (b) La théorie de la collision stellaire prévoit plutôt une matière arrachée au Soleil, donc chaude et de composition semblable à celle du Soleil partout où elle aboutirait. Elle n’offre aucun mécanisme pour trier cette matière selon la distance, rocheuse près du Soleil et gazeuse loin de lui; le gradient observé reste donc sans explication dans cette théorie.<br><br><b>Points d’attribution :</b> 1 point pour le rôle de la température du disque, qui trie les matériaux selon la distance. 1 point pour la matière de collision, uniforme et sans mécanisme de tri selon la distance.", {}); },
  function () { return textq("Un élève affirme : « La théorie de la collision stellaire explique le système solaire aussi bien que l’hypothèse nébulaire. » Évalue cette affirmation à l’aide de l’observation suivante : toutes les planètes orbitent dans le même sens et presque dans le même plan, et leur composition varie régulièrement avec la distance au Soleil. (a) Explique comment l’hypothèse nébulaire rend compte de ces deux régularités à la fois (1 point). (b) Explique pourquoi la théorie de la collision stellaire peine à en rendre compte (1 point). (2 points)", ["(a) un seul nuage en rotation donne le disque, donc le sens et le plan communs, et son gradient de température donne la composition triée selon la distance", "(b) collision : une rencontre unique et désordonnée n’explique ni l’ordre des orbites ni le tri des compositions; l’affirmation de l’élève est donc à rejeter"], "<b>Réponse modèle :</b> (a) L’hypothèse nébulaire explique les deux régularités par un seul point de départ : un nuage en rotation qui se contracte et s’aplatit en disque. Les planètes formées dans ce disque héritent de son sens de rotation et de son plan. Dans le même disque, la température décroît avec la distance, ce qui trie les matériaux : roche et métal près du Soleil chaud, gaz et glaces accumulés loin de lui. (b) La collision stellaire repose sur une rencontre unique et violente : la matière arrachée serait projetée sans ordre prévisible et garderait une composition solaire à peu près uniforme. Elle ne rend compte ni des orbites régulières ni du tri des compositions. L’affirmation de l’élève est donc incorrecte : sur ces observations, l’hypothèse nébulaire explique nettement mieux.<br><br><b>Points d’attribution :</b> 1 point pour le disque unique qui explique à la fois les orbites régulières et le tri des compositions. 1 point pour la collision, désordonnée et uniforme, qui n’explique ni l’une ni l’autre régularité.", {}); },
  function () { return textq("Observation : les huit planètes orbitent dans le même sens, presque dans le même plan, comme si elles provenaient d’un même disque en rotation. (a) Explique comment l’hypothèse nébulaire rend compte de cette observation (1 point). (b) La théorie de la collision stellaire ferait plutôt une autre prévision pour les orbites : énonce cette prévision et explique pourquoi l’observation la contredit (1 point). (2 points)", ["(a) le nuage en rotation s’est aplati en disque; les planètes qui s’y sont formées partagent le sens et le plan du disque", "(b) prévision de la collision : des orbites désordonnées, inclinées au hasard selon la rencontre; l’observation d’orbites régulières et alignées la contredit"], "<b>Réponse modèle :</b> (a) Le nuage de gaz et de poussière à l’origine du système solaire tournait sur lui-même. En se contractant, il s’est aplati en un disque en rotation, et c’est dans ce disque que les planètes se sont formées : elles orbitent donc toutes dans le sens de rotation du disque et presque dans son plan. (b) La collision stellaire prévoirait plutôt des orbites désordonnées : la matière arrachée par une étoile de passage dépendrait de la direction et de la violence de la rencontre, sans raison d’aboutir à des orbites alignées dans un même plan et un même sens. L’alignement régulier observé contredit cette prévision et favorise l’hypothèse nébulaire.<br><br><b>Points d’attribution :</b> 1 point pour le disque en rotation hérité par toutes les planètes. 1 point pour la prévision d’orbites désordonnées propre à la collision, contredite par l’observation.", {}); }
]), ["Un seul nuage de départ doit expliquer la régularité observée; cherche son mécanisme avant de juger la collision.", "Pour la collision, demande-toi ce qu’une rencontre violente et unique produirait de façon réaliste."]);
E("s9f-u1-cr-expansion-preuves", 1, ["SC9.1.5", "SC9.1.7"], 3, "var", varset([
  function () { return textq("La lumière d’une galaxie très lointaine arrive avec ses raies spectrales décalées vers le rouge, et ce décalage est beaucoup plus grand que celui d’une galaxie proche. (a) Explique ce qu’est le décalage vers le rouge (1 point). (b) Indique ce que ce décalage révèle sur le mouvement des galaxies lointaines par rapport à nous (1 point). (c) Explique comment cette observation appuie le modèle du Big Bang (1 point). (d) Situe une nébuleuse à son échelle : compare sa taille à celle d’une étoile et à celle d’une galaxie (1 point). (4 points)", ["(a) la lumière d’une galaxie qui s’éloigne est étirée vers des longueurs d’onde plus grandes, donc décalée vers l’extrémité rouge du spectre", "(b) les galaxies lointaines s’éloignent de nous, et les plus lointaines s’éloignent le plus vite", "(c) un Univers dont toutes les galaxies s’éloignent les unes des autres est un Univers en expansion; en remontant le temps, tout était rassemblé dans un état chaud et dense, comme le décrit le Big Bang", "(d) nébuleuse : immense nuage bien plus grand qu’une étoile, mais contenu à l’intérieur d’une galaxie, donc bien plus petit qu’elle"], "<b>Réponse modèle :</b> (a) Le décalage vers le rouge est le déplacement des raies de la lumière d’un objet vers l’extrémité rouge du spectre, c’est-à-dire vers les grandes longueurs d’onde : la lumière d’une source qui s’éloigne est étirée pendant son trajet. (b) Il révèle que les galaxies lointaines s’éloignent de nous, et que leur vitesse d’éloignement augmente avec leur distance : la galaxie très lointaine, au décalage beaucoup plus grand, s’éloigne beaucoup plus vite que la galaxie proche. (c) Si toutes les galaxies s’éloignent les unes des autres, l’espace lui-même est en expansion. En inversant ce film, on obtient un passé où toute la matière était rassemblée dans un état extrêmement chaud et dense : c’est exactement le point de départ du Big Bang, dont l’expansion observée est la continuation. (d) Une nébuleuse est un immense nuage de gaz et de poussière : elle dépasse de très loin la taille d’une étoile unique, puisqu’elle peut contenir la matière de milliers d’étoiles, mais elle ne forme qu’une petite région à l’intérieur d’une galaxie, qui contient des milliards d’étoiles.<br><br><b>Points d’attribution :</b> 1 point pour la définition du décalage vers le rouge comme étirement de la lumière d’une source qui s’éloigne. 1 point pour l’éloignement des galaxies, plus rapide avec la distance. 1 point pour le lien avec l’expansion et l’état chaud et dense initial du Big Bang. 1 point pour la nébuleuse correctement située entre l’étoile et la galaxie.", {}); },
  function () { return textq("Deux galaxies sont comparées : la galaxie A montre un léger décalage vers le rouge; la galaxie B, beaucoup plus lointaine, montre un décalage vers le rouge deux fois plus grand. (a) Explique ce qu’est le décalage vers le rouge (1 point). (b) Indique ce que la comparaison des deux décalages révèle sur le mouvement des deux galaxies (1 point). (c) Explique comment cette observation appuie le modèle du Big Bang (1 point). (d) Situe un quasar à son échelle : dis ce qu’il est et compare son échelle à celle de la galaxie qui l’abrite (1 point). (4 points)", ["(a) étirement de la lumière d’une source qui s’éloigne, vers les grandes longueurs d’onde du spectre", "(b) les deux galaxies s’éloignent; B, plus lointaine et au décalage double, s’éloigne environ deux fois plus vite que A", "(c) l’éloignement général, ordonné par la distance, est la signature d’un espace en expansion depuis un état initial chaud et dense", "(d) quasar : centre extrêmement brillant d’une galaxie lointaine; sa région émettrice est minuscule à l’échelle de sa galaxie, mais il peut briller plus fort qu’elle tout entière"], "<b>Réponse modèle :</b> (a) Le décalage vers le rouge est l’étirement de la lumière d’une source qui s’éloigne : ses raies spectrales sont déplacées vers les grandes longueurs d’onde, à l’extrémité rouge du spectre. (b) Les deux galaxies s’éloignent de nous. La galaxie B, dont le décalage est le double de celui de A, s’éloigne environ deux fois plus vite que A; or B est aussi la plus lointaine : la vitesse d’éloignement augmente donc avec la distance. (c) Un éloignement général des galaxies, d’autant plus rapide qu’elles sont loin, est exactement ce que produit un espace en expansion. En remontant le temps, cet éloignement conduit à un Univers entièrement rassemblé dans un état chaud et dense : le point de départ du Big Bang, dont l’expansion actuelle est la suite directe. (d) Un quasar est le centre extrêmement brillant d’une galaxie lointaine, alimenté par la matière qui tombe vers son centre. La région qui émet cette lumière est minuscule comparée à la galaxie entière qui l’abrite, et pourtant le quasar peut briller plus fort que toutes les étoiles de cette galaxie réunies : son échelle est donc celle du centre d’une galaxie, pas celle d’une galaxie entière.<br><br><b>Points d’attribution :</b> 1 point pour la définition du décalage vers le rouge comme étirement de la lumière d’une source qui s’éloigne. 1 point pour les deux galaxies qui s’éloignent, la plus lointaine plus vite que l’autre. 1 point pour le lien avec l’expansion et l’état chaud et dense initial du Big Bang. 1 point pour le quasar correctement situé comme centre brillant de sa galaxie.", {}); },
  function () { return textq("Le spectre d’une galaxie spirale lointaine est enregistré : chacune de ses raies caractéristiques se trouve du côté rouge de la position qu’elle occupe dans un spectre produit au laboratoire. (a) Explique ce qu’est ce décalage vers le rouge (1 point). (b) Indique ce qu’il révèle sur le mouvement de cette galaxie par rapport à nous (1 point). (c) Explique comment cette observation, répétée pour de nombreuses galaxies, appuie le modèle du Big Bang (1 point). (d) Situe la galaxie spirale elle-même à son échelle : compare-la à une étoile unique (1 point). (4 points)", ["(a) les raies sont déplacées vers les grandes longueurs d’onde parce que la lumière est étirée par l’éloignement de la source", "(b) la galaxie s’éloigne de nous; l’espace entre elle et nous grandit", "(c) presque toutes les galaxies lointaines montrent ce décalage, d’autant plus grand qu’elles sont loin : l’Univers entier est en expansion, comme le prévoit le Big Bang depuis un état chaud et dense", "(d) une galaxie spirale est un ensemble de milliards d’étoiles, de gaz et de poussière : elle est incomparablement plus grande qu’une étoile unique"], "<b>Réponse modèle :</b> (a) Le décalage vers le rouge est le déplacement des raies d’un spectre vers les grandes longueurs d’onde, du côté rouge. Il se produit parce que la lumière d’une source qui s’éloigne est étirée pendant son trajet jusqu’à nous. (b) Il révèle que cette galaxie s’éloigne de nous : ce n’est pas un simple déplacement local, car le même phénomène, mesuré dans toutes les directions, montre que l’espace entre les galaxies grandit. (c) Répétée pour de nombreuses galaxies, l’observation dessine un tableau cohérent : presque toutes les galaxies lointaines s’éloignent, et d’autant plus vite qu’elles sont loin. C’est la signature d’un Univers en expansion. En remontant cette expansion, on aboutit à un état initial extrêmement chaud et dense, celui du Big Bang. (d) Une galaxie spirale est un ensemble immense de milliards d’étoiles, de gaz et de poussière, organisé en bras autour d’un centre : une étoile unique n’est qu’un de ses milliards de constituants, sans commune mesure avec l’ensemble.<br><br><b>Points d’attribution :</b> 1 point pour la définition du décalage vers le rouge comme étirement de la lumière d’une source qui s’éloigne. 1 point pour la galaxie qui s’éloigne de nous. 1 point pour l’expansion générale des galaxies reliée à l’état chaud et dense initial du Big Bang. 1 point pour la galaxie spirale correctement située comme ensemble de milliards d’étoiles.", {}); },
  function () { return textq("Une galaxie relativement proche montre un faible décalage vers le rouge, tandis qu’une galaxie extrêmement lointaine montre un décalage vers le rouge très important. (a) Explique ce qu’est le décalage vers le rouge (1 point). (b) Indique ce que la différence entre les deux décalages révèle sur le mouvement des galaxies (1 point). (c) Explique comment cette observation appuie le modèle du Big Bang (1 point). (d) Situe une étoile de faible masse à son échelle : compare sa taille à celle d’une nébuleuse (1 point). (4 points)", ["(a) déplacement des raies lumineuses vers le rouge, causé par l’étirement de la lumière d’une source qui s’éloigne", "(b) les deux galaxies s’éloignent, mais la plus lointaine s’éloigne beaucoup plus vite : la vitesse d’éloignement croît avec la distance", "(c) cette expansion générale, mesurée dans toutes les directions, correspond à un Univers qui grandit depuis un état initial chaud et dense", "(d) une étoile de faible masse est un corps unique de gaz en fusion, minuscule à l’échelle d’une nébuleuse, immense nuage qui s’étend sur des années-lumière"], "<b>Réponse modèle :</b> (a) Le décalage vers le rouge est le déplacement des raies de la lumière d’un objet vers l’extrémité rouge du spectre, vers les grandes longueurs d’onde. Il survient quand la source s’éloigne : sa lumière est étirée pendant le trajet. (b) Les deux galaxies s’éloignent de nous, mais pas à la même vitesse : la galaxie extrêmement lointaine, au décalage très important, s’éloigne beaucoup plus vite que la galaxie proche, au faible décalage. La vitesse d’éloignement croît donc avec la distance. (c) Cette relation, observée pour les galaxies dans toutes les directions, décrit un Univers en expansion : chaque galaxie s’éloigne des autres parce que l’espace grandit. En inversant le mouvement, tout converge vers un état initial chaud et dense, le point de départ du Big Bang; l’observation appuie donc directement ce modèle. (d) Une étoile de faible masse est un corps unique de gaz en fusion. Une nébuleuse est un nuage immense qui s’étend sur des années-lumière et peut contenir la matière de très nombreuses étoiles : l’étoile de faible masse est donc minuscule à l’échelle de la nébuleuse où de telles étoiles naissent.<br><br><b>Points d’attribution :</b> 1 point pour la définition du décalage vers le rouge comme étirement de la lumière d’une source qui s’éloigne. 1 point pour la vitesse d’éloignement qui croît avec la distance. 1 point pour le lien avec l’expansion et l’état chaud et dense initial du Big Bang. 1 point pour l’étoile de faible masse correctement située comme bien plus petite qu’une nébuleuse.", {}); }
]), ["Le décalage vers le rouge se lit comme une mesure d’éloignement : plus il est grand, plus la source est lointaine et rapide.", "Pour la composante demandée, compare toujours son échelle à deux repères : l’étoile et la galaxie."]);

/* ---------- Ajout du 21 novembre 2026 : plan de tests (decisions 9, 10, 11) ---------- */
E("s9f-u1-systeme-formation", 1, ["SC9.1.2"], 2, "var", varset([
  function () { return mcq("Un immense nuage de gaz et de poussière se contracte lentement sous l'effet de sa propre gravité. Selon l'hypothèse de la nébuleuse, quelle suite d'événements conduit à la formation des planètes?", "Le nuage s'aplatit en disque en tournant, son centre forme le Soleil, puis les grains du disque s'agglomèrent en planètes", ["Le nuage s'aplatit en disque en tournant, son centre forme le Soleil, puis les grains du disque se dispersent en comètes", "Le nuage se fragmente en éclats en tournant, ses éclats forment le Soleil, puis les débris voisins retombent en planètes", "Le nuage s'échauffe sans tourner, son centre forme le Soleil, puis la matière projetée au hasard se condense en planètes"], "Selon l'hypothèse de la nébuleuse, le nuage en contraction tourne de plus en plus vite et s'aplatit en disque. La matière du centre, très dense et très chaude, devient le Soleil, tandis que les grains de gaz et de poussière du disque entrent en collision, se collent et grossissent jusqu'à former les planètes.", {}); },
  function () { return mcq("Des astronomes observent une étoile très jeune entourée d'un disque plat de gaz et de poussière, avec des anneaux sombres dans le disque. Pourquoi cette observation appuie-t-elle l'hypothèse de la nébuleuse?", "Elle montre un disque semblable à celui où le Soleil et ses planètes se seraient formés, avec des vides creusés par des planètes naissantes", ["Elle montre un disque semblable à celui où le Soleil et ses planètes se seraient formés, avec des vides creusés par des comètes vieillissantes", "Elle montre une étoile semblable au Soleil entourée des restes d'une autre étoile, avec des vides creusés par des planètes naissantes", "Elle montre un nuage sphérique sans rotation autour d'une étoile âgée, avec des vides creusés par des planètes naissantes"], "L'hypothèse de la nébuleuse prévoit qu'un nuage qui se contracte en tournant forme un disque où naissent les planètes. Observer aujourd'hui une étoile jeune entourée d'un tel disque, déjà marqué par des anneaux où la matière s'agglomère, correspond exactement à l'étape prévue par l'hypothèse.", {}); },
  function () { return mcq("Dans un modèle de classe, une patineuse qui tourne ramène ses bras contre son corps et tourne soudain plus vite. Un élève fait le lien avec la formation du système solaire. Quel lien est correct?", "Comme la patineuse, le nuage qui se contracte tourne plus vite en se resserrant, ce qui l'aplatit en disque autour du futur Soleil", ["Comme la patineuse, le nuage qui se dilate tourne plus vite en s'étalant, ce qui l'aplatit en disque autour du futur Soleil formé", "Comme la patineuse, le nuage qui se contracte tourne moins vite en se resserrant, ce qui le gonfle en sphère autour du futur Soleil", "Comme la patineuse, le nuage qui se réchauffe tourne plus vite en se vaporisant, ce qui le disperse en anneau autour du futur Soleil"], "Un nuage qui se contracte conserve son mouvement de rotation : en se resserrant, il tourne de plus en plus vite, comme la patineuse qui ramène ses bras. Cette rotation rapide aplatit le nuage en disque, et c'est dans ce disque que le Soleil, au centre, et les planètes se sont formés.", {}); },
  function () { return mcq("Une équipe présente la formation du système solaire en quatre étapes, mais dans le désordre : (1) les grains du disque se collent et grossissent; (2) le nuage de gaz et de poussière se contracte; (3) le centre du disque devient le Soleil; (4) le nuage en rotation s'aplatit en disque. Quel ordre correspond à l'hypothèse de la nébuleuse?", "D'abord la contraction du nuage, puis son aplatissement en disque, puis la naissance du Soleil au centre, puis la croissance des grains en planètes", ["D'abord la contraction du nuage, puis la naissance du Soleil au centre, puis son aplatissement en disque, puis la croissance des grains en planètes", "D'abord l'aplatissement en disque, puis la contraction du nuage, puis la croissance des grains en planètes, puis la naissance du Soleil au centre", "D'abord la croissance des grains en planètes, puis la contraction du nuage, puis son aplatissement en disque, puis la naissance du Soleil au centre"], "La séquence de l'hypothèse de la nébuleuse commence par la contraction du nuage. Sa rotation l'aplatit ensuite en disque, la matière centrale devient le Soleil, et les grains restés dans le disque s'agglomèrent enfin en planètes. Aucune planète ne peut se former avant le disque qui lui fournit sa matière.", {}); },
  function () { return mcq("Les analyses de météorites anciennes et des roches lunaires donnent au Soleil et aux planètes le même âge, environ 4,6 milliards d'années, et des compositions apparentées. Pourquoi ce résultat convient-il à l'hypothèse de la nébuleuse?", "Parce qu'elle fait naître le Soleil et les planètes en même temps, à partir du même nuage de matière au départ de tout le système", ["Parce qu'elle fait naître le Soleil et les planètes en même temps, à partir de deux nuages distincts au départ de tout le système", "Parce qu'elle fait naître les planètes longtemps après le Soleil, à partir du même nuage de matière au départ de tout le système", "Parce qu'elle fait naître le Soleil longtemps après les planètes, à partir du même nuage de matière au départ de tout le système"], "Si le Soleil et les planètes proviennent du même nuage, comme le propose l'hypothèse de la nébuleuse, ils doivent partager le même âge et des compositions apparentées. Des âges très différents, ou des matières sans lien, contrediraient une origine commune dans un seul nuage.", {}); }
]), ["Suis la séquence : contraction, rotation, disque, puis Soleil et planètes.", "Le Soleil et les planètes partagent le même nuage de départ."]);
E("s9f-u1-phenomenes-solaires", 1, ["SC9.1.4"], 2, "var", varset([
  function () { return mcq("Après une nuit d'activité solaire intense, des aurores sont visibles beaucoup plus au sud que d'habitude, jusque dans le sud du Canada. Quelle explication relie le mieux ce spectacle au Soleil?", "Une bouffée renforcée du vent solaire a atteint la Terre, et ses particules, guidées vers les pôles, ont fait briller les gaz sur une zone élargie", ["Une bouffée renforcée de lumière solaire a atteint la Terre, et ses rayons, guidés vers les pôles, ont fait briller les gaz sur une zone élargie", "Une bouffée renforcée de chaleur solaire a atteint la Terre, et son énergie, guidée vers les pôles, a fait fondre les gaz sur une zone élargie", "Une marée renforcée par le Soleil a atteint la Terre, et son attraction, guidée vers les pôles, a fait briller les gaz sur une zone élargie"], "Les aurores naissent quand les particules chargées du vent solaire frappent les gaz de la haute atmosphère. Quand le vent solaire est renforcé par l'activité du Soleil, davantage de particules arrivent et la zone où les gaz brillent s'élargit : les aurores deviennent visibles plus loin des pôles que d'habitude.", {}); },
  function () { return mcq("Un avion qui survole l'Arctique perd soudain le contact radio avec la tour de contrôle, peu après l'annonce d'une forte éruption solaire. Quel lien entre les deux événements est le plus plausible?", "Les particules projetées par l'éruption ont perturbé la haute atmosphère, qui a brouillé les signaux radio utilisés par l'avion en vol polaire", ["Les particules projetées par l'éruption ont réchauffé la haute atmosphère, qui a fait fondre les signaux radio utilisés par l'avion en vol", "La lumière projetée par l'éruption a ébloui la haute atmosphère, qui a brouillé les signaux radio utilisés par l'avion en vol polaire", "Les comètes projetées par l'éruption ont traversé la haute atmosphère, qui a brouillé les signaux radio utilisés par l'avion en vol polaire"], "Une forte éruption solaire projette un surplus de particules chargées. En atteignant la Terre, elles perturbent la haute atmosphère, la couche qui réfléchit et conduit certains signaux radio. Les communications, surtout sur les trajets polaires, peuvent alors être brouillées ou interrompues pendant des heures.", {}); },
  function () { return mcq("Pendant une tempête solaire majeure, un transformateur d'un réseau électrique grille et une partie d'une province perd le courant. Quelle chaîne d'événements explique le mieux cette panne?", "Les particules de la tempête ont fait varier le champ magnétique terrestre, ce qui a induit des courants supplémentaires dans les longues lignes du réseau", ["Les particules de la tempête ont fait varier la température du sol, ce qui a induit des courants supplémentaires dans les longues lignes du réseau visé", "La chaleur de la tempête a fait varier le champ magnétique terrestre, ce qui a fait fondre des courants supplémentaires dans les longues lignes du réseau", "Les particules de la tempête ont fait varier la gravité terrestre, ce qui a induit des courants supplémentaires dans les longues lignes du réseau visé"], "Les particules d'une tempête solaire déclenchent une tempête géomagnétique : le champ magnétique terrestre varie rapidement. Ces variations induisent des courants supplémentaires dans les très longues lignes électriques; les transformateurs, conçus pour le courant normal, peuvent alors surchauffer et griller.", {}); },
  function () { return mcq("Les opérateurs d'un satellite de communication apprennent qu'une masse de particules s'échappe du Soleil en direction de la Terre. Ils placent le satellite en mode protégé pour deux jours. Pourquoi cette précaution est-elle raisonnable?", "Les particules chargées qui atteindront le satellite peuvent endommager ses circuits et brouiller ses transmissions pendant le passage de la bouffée solaire", ["Les particules chargées qui atteindront le satellite peuvent refroidir ses circuits et brouiller ses transmissions pendant le passage de la bouffée solaire", "La chaleur chargée qui atteindra le satellite peut endommager ses circuits et brouiller ses transmissions pendant le passage de la bouffée solaire prévue", "Les particules chargées qui atteindront le satellite peuvent l'attirer hors de son orbite pendant le passage complet de la bouffée solaire annoncée"], "Hors de la protection de la basse atmosphère, un satellite reçoit de plein fouet les particules chargées du vent solaire renforcé. Elles peuvent perturber ou endommager ses circuits électroniques et brouiller ses signaux. Le mode protégé réduit ces risques pendant le passage de la bouffée.", {}); },
  function () { return mcq("Un soir d'hiver, le ciel d'une ville nordique s'illumine de rubans verts mouvants, alors qu'au même moment, des opérateurs radio signalent des communications difficiles. Quelle cause commune explique ces deux observations?", "Une activité solaire renforcée : ses particules produisent les aurores dans la haute atmosphère et y perturbent en même temps les signaux radio terrestres", ["Une activité solaire renforcée : sa lumière produit les aurores dans la haute atmosphère et y perturbe en même temps les signaux radio terrestres captés", "Une activité lunaire renforcée : ses particules produisent les aurores dans la haute atmosphère et y perturbent en même temps les signaux radio terrestres", "Une activité solaire renforcée : sa chaleur produit les aurores dans la haute atmosphère et y fait fondre en même temps les signaux radio terrestres"], "Les deux observations ont la même source : un vent solaire renforcé. Ses particules chargées font briller les gaz de la haute atmosphère, ce qui donne les aurores, et leur arrivée perturbe cette même couche de l'atmosphère, dont dépendent plusieurs communications radio.", {}); }
]), ["Cherche la cause commune : des particules chargées venues du Soleil.", "Aurores, radios et réseaux électriques réagissent à la même tempête solaire."]);
E("s9f-u1-univers-origine", 1, ["SC9.1.5"], 2, "var", varset([
  function () { return mcq("Un télescope mesure la température du rayonnement fossile : environ 2,7 degrés au-dessus du zéro absolu, partout dans le ciel. Un élève demande pourquoi un rayonnement si froid appuie l'idée d'un début très chaud. Quelle réponse est exacte?", "En s'étendant depuis son état chaud et dense, l'Univers s'est refroidi; ce rayonnement est la chaleur restante de ses débuts, étirée par l'expansion continue", ["En s'étendant depuis son état chaud et dense, l'Univers s'est réchauffé; ce rayonnement est la chaleur restante de ses débuts, étirée par l'expansion continue", "En se contractant depuis son état chaud et dense, l'Univers s'est refroidi; ce rayonnement est la chaleur restante de ses débuts, étirée par la contraction", "En restant inchangé depuis son état chaud et dense, l'Univers s'est refroidi; ce rayonnement est la chaleur restante de ses débuts, étirée par son immobilité"], "La théorie du Big Bang prévoit qu'un Univers né extrêmement chaud laisse, après des milliards d'années d'expansion et de refroidissement, un faible rayonnement résiduel dans toutes les directions. Le rayonnement fossile mesuré correspond à cette prévision : c'est la signature refroidie d'un début chaud et dense.", {}); },
  function () { return mcq("En pensée, des astronomes font jouer l'expansion de l'Univers à rebours, comme un film inversé. À quoi cette démarche les conduit-elle, et pourquoi appuie-t-elle la théorie du Big Bang?", "Les galaxies se rapprochent jusqu'à un état unique, chaud et dense : c'est l'état de départ que la théorie du Big Bang décrit pour tout l'Univers entier", ["Les galaxies se rapprochent jusqu'à un état unique, froid et vide : c'est l'état de départ que la théorie du Big Bang décrit pour tout l'Univers entier", "Les galaxies s'éloignent jusqu'à un état dispersé, chaud et dense : c'est l'état de départ que la théorie du Big Bang décrit pour tout l'Univers entier", "Les galaxies restent à distance constante, dans un état chaud et dense : c'est l'état de départ que la théorie du Big Bang décrit pour l'Univers"], "Si les galaxies s'éloignent aujourd'hui les unes des autres, alors en remontant le temps elles devaient être de plus en plus rapprochées. Poussée jusqu'au bout, cette logique aboutit à un état unique, extrêmement chaud et dense : exactement le point de départ de la théorie du Big Bang.", {}); },
  function () { return mcq("Les télescopes les plus puissants montrent que les galaxies très lointaines, vues telles qu'elles étaient il y a des milliards d'années, sont plus petites et plus irrégulières que les galaxies actuelles. Pourquoi cette observation convient-elle à la théorie du Big Bang?", "Parce qu'elle montre un Univers qui a changé avec le temps, depuis un état jeune et différent vers l'état actuel, comme le prévoit une évolution depuis un début chaud", ["Parce qu'elle montre un Univers qui n'a jamais changé avec le temps, depuis un état jeune et différent vers l'état actuel, comme le prévoit une évolution lente", "Parce qu'elle montre un Univers qui a changé avec le temps, depuis un état ancien identique vers l'état actuel, comme le prévoit une évolution depuis un début froid", "Parce qu'elle montre un Univers qui a changé avec le temps, depuis un état jeune et différent vers l'état final, comme le prévoit une théorie d'Univers éternel figé"], "Regarder loin, c'est regarder dans le passé, car la lumière a mis des milliards d'années à nous parvenir. Voir des galaxies jeunes différentes des galaxies actuelles montre un Univers en évolution, né dans un état chaud et dense, et non un Univers éternel et inchangé.", {}); },
  function () { return mcq("Deux galaxies sont comparées : la galaxie A est deux fois plus loin que la galaxie B, et son décalage vers le rouge indique qu'elle s'éloigne environ deux fois plus vite. Quelle lecture de cette observation est correcte?", "L'éloignement proportionnel à la distance dessine une expansion générale de l'espace, où chaque galaxie s'écarte des autres sans centre privilégié dans l'Univers", ["L'éloignement proportionnel à la distance dessine une explosion ordinaire de débris, où chaque galaxie s'écarte des autres depuis un centre privilégié unique", "L'éloignement proportionnel à la distance dessine une contraction générale de l'espace, où chaque galaxie s'écarte des autres sans centre privilégié dans l'Univers", "L'éloignement proportionnel à la distance dessine une rotation générale de l'espace, où chaque galaxie s'écarte des autres sans centre privilégié dans l'Univers"], "Quand la vitesse d'éloignement croît régulièrement avec la distance, le motif observé est celui d'une expansion de l'espace lui-même : de n'importe quelle galaxie, toutes les autres semblent s'éloigner selon la même règle. Il n'y a ni centre ni explosion ordinaire de débris dans un espace déjà existant.", {}); },
  function () { return mcq("Un élève résume ainsi une observation : « Partout où l'on regarde, les galaxies s'éloignent, et l'espace entre elles grandit sans cesse. » Quelle conclusion, tirée de cette seule observation, appuie directement la théorie du Big Bang?", "L'Univers est en expansion, donc il était plus petit, plus chaud et plus dense dans le passé, comme l'affirme la théorie du Big Bang à son point de départ", ["L'Univers est en expansion, donc il était plus grand, plus chaud et plus dense dans le passé, comme l'affirme la théorie du Big Bang à son point de départ", "L'Univers est immobile, donc il était plus petit, plus chaud et plus dense dans le passé, comme l'affirme la théorie du Big Bang à son point de départ", "L'Univers est en contraction, donc il était plus petit, plus chaud et plus dense dans le passé, comme l'affirme la théorie du Big Bang au départ"], "L'expansion actuelle, projetée vers le passé, implique un Univers autrefois plus compact. Un passé plus petit signifie aussi plus chaud et plus dense, puisque la même matière et la même énergie occupaient moins d'espace : c'est le cœur de la théorie du Big Bang.", {}); }
]), ["Trois appuis reviennent : expansion, décalage vers le rouge et rayonnement fossile.", "Regarder loin dans l'espace, c'est aussi regarder loin dans le passé."]);
